const base = '4bc857dfeff81dbb063347b70bb4436bebaa48b7';
const repo = 'John-River/Firefly';
const token = process.env.GITHUB_TOKEN;
if (!token) throw new Error('GITHUB_TOKEN build secret is required.');
async function api(path, data, method='POST') {
 const response=await fetch('https://api.github.com/repos/'+repo+'/'+path,{method:data===undefined?'GET':method,headers:{Authorization:'Bearer '+token,Accept:'application/vnd.github+json','User-Agent':'Firefly-Admin-Installer','Content-Type':'application/json','X-GitHub-Api-Version':'2022-11-28'},...(data===undefined?{}:{body:JSON.stringify(data)})});
 if(!response.ok) throw new Error('GitHub request failed: '+response.status+' '+path);
 return response.json();
}
const current=await api('git/ref/heads/master');
const head=await api('git/commits/'+current.object.sha);
const [before,now]=await Promise.all([api('git/trees/'+base+'?recursive=1'),api('git/trees/'+head.tree.sha+'?recursive=1')]);
if(before.truncated||now.truncated) throw new Error('Repository tree is truncated.');
for(const f of files){
 const previous=before.tree.find(x=>x.path===f.path)?.sha;
 const latest=now.tree.find(x=>x.path===f.path)?.sha;
 if(previous!==latest) throw new Error('Concurrent file change: '+f.path);
}
for(const f of files){fs.mkdirSync(f.path.split('/').slice(0,-1).join('/')||'.',{recursive:true});fs.writeFileSync(f.path,f.content);}
const entries=[];
for(const f of files){const blob=await api('git/blobs',{content:f.content,encoding:'utf-8'});entries.push({path:f.path,mode:'100644',type:'blob',sha:blob.sha});}
entries.push({path:'admin-bootstrap.mjs',mode:'100644',type:'blob',sha:null});
const tree=await api('git/trees',{base_tree:head.tree.sha,tree:entries});
const commit=await api('git/commits',{message:'Add password-protected blog writing admin trial',tree:tree.sha,parents:[current.object.sha]});
await api('git/refs/heads/master',{sha:commit.sha,force:false},'PATCH');
console.log('Admin source installed in GitHub commit '+commit.sha);

